{
  "API_calls": [],
  "collected_information": {
    "requirements.txt": {
      "dependencies": {
        "aiohttp": "3.10.5",
        "numpy": "1.26.4",
        "openai": "1.47.0",
        "pydantic": "2.9.2",
        "requests": "2.32.3",
        "scipy": "1.13.1"
      },
      "install_command": "pip install -r requirements.txt"
    },
    "requirements/requirements-dev.txt": {
      "dev_dependencies": {
        "pytest": "8.3.3",
        "pre-commit": "3.8.0",
        "sphinx": "7.4.7",
        "black": "tooling"
      },
      "install_command": "pip install -r requirements/requirements-dev.txt"
    },
    "pyproject.toml": {
      "python_version": ">=3.9,<3.13",
      "package_name": "aider-chat",
      "build_system": "setuptools",
      "entry_point": "aider = \"aider.main:main\"",
      "development_status": "Beta",
      "url": "https://github.com/Aider-AI/aider"
    },
    "README.md": {
      "installation": "python -m pip install -U aider-chat",
      "environment_variables": [
        "export ANTHROPIC_API_KEY=your-key",
        "export OPENAI_API_KEY=your-key"
      ],
      "run_command": "aider"
    },
    "CONTRIBUTING.md": {
      "dev_setup": [
        "Create Python 3.9+ virtual environment",
        "Activate and pip install -e .",
        "pip install -r requirements.txt",
        "pip install -r requirements/requirements-dev.txt",
        "pre-commit install (optional)"
      ]
    },
    "docker/Dockerfile": {
      "base_image": "python:3.10-slim",
      "system_packages": [
        "build-essential",
        "git",
        "libportaudio2",
        "pandoc"
      ],
      "python_virtualenv_path": "/venv",
      "python_package_install": [
        "local aider package with extras [help,browser,playwright] or [playwright]",
        "PyTorch CPU wheels from official CPU wheel index"
      ],
      "playwright_browsers": ["chromium"],
      "environment_variables": {
        "PATH": "/venv/bin",
        "PLAYWRIGHT_BROWSERS_PATH": "/pw-browsers"
      },
      "git_and_permissions": {
        "git_safe_directory": true,
        "directory_permissions_set": true
      }
    },
    "CI_files": {
      "location": ".github/workflows/",
      "not_extracted_info": true
    }
  },
  "terminate": true
}
